"""Column definitions shared by every table."""

import uuid
from datetime import datetime
from decimal import Decimal
from typing import Annotated

from sqlalchemy import Numeric, func, text
from sqlalchemy.orm import mapped_column

# UUIDv7 primary key generated by Postgres 18 (hard rule 8).
UuidPk = Annotated[uuid.UUID, mapped_column(primary_key=True, server_default=text("uuidv7()"))]

CreatedAt = Annotated[datetime, mapped_column(server_default=func.now())]

# Cost of one base unit (g, ml or piece). Six decimals, because a pack price spread
# over thousands of base units is tiny: 0.850 for 1000 ml is 0.000850 per ml. Other
# money and quantities stay numeric(14,3), the type map's default for Decimal.
UnitCost = Annotated[Decimal, mapped_column(Numeric(18, 6))]
